I like to use a 'Click and Hold' to edit the cells: dataGridView_List is the name of my DataGridViewDataGridView EditMode Property is set to EditProgrammaticallyCreate a class to key track of cell and a timer (with a hold time - say 500milliseconds) and then use CellMouseDown/Up events to start/stop timer   public class cellEdit    {        int Row;        int Col;        readonly int elapsedtime;        readonly Stopwatch SW;        public cellEdit(int iElapsedTimeInMillisecons)        {            elapsedtime = iElapsedTimeInMillisecons;            SW = Stopwatch.StartNew();        }        public void Start(int iRow, int iCol)        {            {                Row = iRow;                Col = iCol;                SW.Restart();            }        }        public bool Stop(int iRow, int iCol)        {            SW.Stop();            if (iRow == Row && iCol == Col) if (SW.ElapsedMilliseconds > elapsedtime) return true;            return false;        }    }in Form    public cellEdit GetCellEdit = new GetCellEdit(500);  // 500mSadd datagridview CellMouseUp and CellMouseDown events    private void dataGridView_List_CellMouseDown(object sender, DataGridViewCellMouseEventArgs e)    {        if (e.RowIndex > 0 && e.RowIndex < dataGridView_List.Rows.Count && e.ColumnIndex > 0 && e.ColumnIndex < dataGridView_List.Columns.Count)            GetCellEdit.Start(e.RowIndex, e.ColumnIndex);    }    private void dataGridView_List_CellMouseUp(object sender, DataGridViewCellMouseEventArgs e)    {        if (e.RowIndex > 0 && e.RowIndex < dataGridView_List.Rows.Count && e.ColumnIndex > 0 && e.ColumnIndex < dataGridView_List.Columns.Count)            if (GetCellEdit.Stop(e.RowIndex, e.ColumnIndex))            {                dataGridView_List.CurrentCell = dataGridView_List.Rows[e.RowIndex].Cells[e.ColumnIndex];                dataGridView_List.BeginEdit(false);            }    }Now cell goes into edit mode if you click and hold the mouse for 1/2 second